def render_icon(name: str, size: int = 20, label: str | None = None) -> Markup:
    """SVG markup for a named icon. Decorative by default (hidden from screen
    readers); pass a label when the icon is the only content of a control."""
    try:
        path = PATHS[name]
    except KeyError:
        raise KeyError(f"Unknown icon {name!r}; available: {', '.join(sorted(PATHS))}") from None
    # Markup.format escapes every argument that is not already Markup.
    a11y = LABELLED.format(label) if label else DECORATIVE
    return SVG_TEMPLATE.format(size=int(size), a11y=a11y, path=path)
